نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
به‌عنوان مدیرعامل می‌خواهم بدانم مهم‌ترین ریسک مالی این ماه از نگاه تو چیست و کجا باید تمرکز کنیم. (مدیر مالی در گفتگو با مدیرعامل — تولیدی تجهیزات صنعتی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "receivables_aging",
      "description": "سن مطالبات به تفکیک مشتری و بازهٔ سنی",
      "dimensions": [
        "customer",
        "aging_bucket"
      ],
      "measures": [
        "balance"
      ]
    },
    {
      "dataset": "sales_by_product",
      "description": "فروش و حاشیه به تفکیک محصول",
      "dimensions": [
        "product",
        "period"
      ],
      "measures": [
        "sales",
        "gross_margin_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "operating_profit",
      "description": "سود عملیاتی",
      "formula": "حاشیهٔ ناخالص - هزینه‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "operating_cash_flow",
      "description": "جریان نقد عملیاتی",
      "formula": "دریافت‌ها از عملیات - پرداخت‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات / فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "customer",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "operating_profit",
    "period_a": "prev_quarter",
    "period_b": "curr_quarter"
  }
}

TOOL_OBSERVATION:
{
  "operating_profit": {
    "prev": 140,
    "curr": 185,
    "growth_pct": 32
  }
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "operating_cash_flow",
    "period_a": "prev_quarter",
    "period_b": "curr_quarter"
  }
}

TOOL_OBSERVATION:
{
  "operating_cash_flow": {
    "prev": 120,
    "curr": -105,
    "note": "منفی شدن هم‌زمان با رشد فروش نسیه"
  }
}

TOOL_CALL:
{
  "tool": "get_top_bottom",
  "arguments": {
    "metric": "dso",
    "dimension": "customer",
    "n": 3,
    "order": "desc"
  }
}

TOOL_OBSERVATION:
{
  "top_dso": [
    {
      "customer": "مشتری بزرگ الف",
      "dso_days": 86,
      "share_of_sales_pct": 36
    }
  ]
}

نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
چرخهٔ تبدیل وجه نقد ما نسبت به فصل قبل 32 روز بلندتر شده و پول در حساب‌های دریافتنی خوابیده. دقیقاً کجای زنجیرهٔ نقد شکسته؟ می‌خواهم روی همان نقطه تمرکز کنم. (مدیر مالی — فرآوری لبنی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "working_capital_breakdown",
      "description": "اجزای سرمایه در گردش و روزهای هر جزء",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "amount",
        "days"
      ]
    },
    {
      "dataset": "receivables_aging",
      "description": "سن مطالبات به تفکیک مشتری و بازهٔ سنی",
      "dimensions": [
        "customer",
        "aging_bucket"
      ],
      "measures": [
        "balance"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ccc",
      "description": "چرخهٔ تبدیل وجه نقد",
      "formula": "dio + dso - dpo",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات / فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "customer",
        "period"
      ]
    },
    {
      "metric": "dio",
      "description": "دورهٔ گردش موجودی",
      "formula": "موجودی / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dpo",
      "description": "دورهٔ پرداخت بستانکاران",
      "formula": "بستانکاران / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ccc"
    ],
    "period": [
      "prev_quarter",
      "curr_quarter"
    ],
    "comparison": "quarter_over_quarter"
  }
}

TOOL_OBSERVATION:
{
  "ccc_days": {
    "prev_quarter": 27,
    "curr_quarter": 59,
    "change": 32
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "working_capital_breakdown",
    "filters": {
      "period": [
        "prev_quarter",
        "curr_quarter"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "components_days": {
    "dio": {
      "prev": 18,
      "curr": 23
    },
    "dso": {
      "prev": 37,
      "curr": 65
    },
    "dpo": {
      "prev": 28,
      "curr": 29
    }
  },
  "receivables_m_toman": {
    "prev": 666,
    "curr": 1170
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "receivables_aging",
    "filters": {
      "period": "curr_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "aging_top": {
    "مشتری دولتی X": {
      "balance_m_toman": 702,
      "aging_days": 92,
      "share_of_new_sales_pct": 38
    },
    "سایر مشتریان": {
      "balance_m_toman": 468,
      "aging_days": 30
    }
  },
  "note": "قرارداد جدید سه‌ماهه با مشتری دولتی X با دورهٔ پرداخت ۹۰ روز و بدون ضمانت‌نامه بانکی؛ سهم 38٪ از فروش نسیهٔ جدید"
}

نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
سود عملیاتی این ماه نسبت به ماه قبل حدود 26٪ کم شده در حالی که فروش تقریباً ثابت است. دقیقاً کدام ردیف باعث افت شده؟ (مدیر مالی — تولیدی تجهیزات صنعتی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "income_statement",
      "description": "صورت سود و زیان دوره به تفکیک خط",
      "dimensions": [
        "period",
        "line"
      ],
      "measures": [
        "amount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "bad_debt_provision",
      "description": "ذخیرهٔ مطالبات مشکوک‌الوصول",
      "formula": "ذخیرهٔ ثبت‌شده در دوره",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "operating_profit",
      "description": "سود عملیاتی",
      "formula": "حاشیهٔ ناخالص - هزینه‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "income_statement",
    "filters": {
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "income_statement": {
    "prev_month": {
      "sales": 710,
      "gross_profit": 213,
      "opex": 107,
      "operating_profit": 106
    },
    "curr_month": {
      "sales": 731,
      "gross_profit": 219,
      "opex": 141,
      "operating_profit": 78
    }
  }
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "bad_debt_provision"
    ],
    "period": "curr_month",
    "comparison": "prev_month"
  }
}

TOOL_OBSERVATION:
{
  "bad_debt_provision": {
    "curr_month": 28,
    "prev_month": 0,
    "note": "ذخیرهٔ کامل مطالبات یک مشتری ورشکسته (یکجا)"
  }
}

