نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
این ماه سود عملیاتی رشد کرده ولی موجودی نقد افت کرده. به نظر من سودآوری دارد نقدینگی ما را می‌خورد و باید فروش نسیه را متوقف کنیم. قبل از هر تصمیمی دلیل واقعی را بگو. (مدیر مالی — گروه صنعتی پارس)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "cash_flow_statement",
      "description": "صورت جریان وجوه نقد دوره به تفکیک بخش",
      "dimensions": [
        "period",
        "section"
      ],
      "measures": [
        "amount"
      ]
    },
    {
      "dataset": "monthly_cash_position",
      "description": "موجودی نقد پایان ماه",
      "dimensions": [
        "month"
      ],
      "measures": [
        "balance"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "operating_profit",
      "description": "سود عملیاتی",
      "formula": "حاشیهٔ ناخالص - هزینه‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "cash_balance",
      "description": "موجودی نقد پایان دوره",
      "formula": "جمع ورودی و خروجی‌های نقد",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "operating_profit",
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "operating_profit": {
    "prev": 185,
    "curr": 244,
    "growth_m_toman": 59
  },
  "breakdown": {
    "رشد حاشیهٔ صادرات (افزایش نرخ ارز تسعیر)": 59
  }
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "cash_balance",
    "granularity": "month",
    "range": "last_2_months"
  }
}

TOOL_OBSERVATION:
{
  "cash_balance": {
    "prev_month_end": 151,
    "curr_month_end": 85,
    "drop_m_toman": 66
  },
  "outflows": {
    "خرید یکجای مواد اولیهٔ پروژهٔ جدید (انبارش)": 90,
    "پرداخت سود سالانهٔ تسهیلات": 27
  },
  "inflows": {
    "ورودی عملیاتی مازاد": 51
  }
}

