چرخهٔ تبدیل وجه نقد ما نسبت به فصل قبل 23 روز بلندتر شده و پول در حساب‌های دریافتنی خوابیده. دقیقاً کجای زنجیرهٔ نقد شکسته؟ می‌خواهم روی همان نقطه تمرکز کنم. (مدیر مالی — گروه صنعتی پارس)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "working_capital_breakdown",
      "description": "اجزای سرمایه در گردش و روزهای هر جزء",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "amount",
        "days"
      ]
    },
    {
      "dataset": "receivables_aging",
      "description": "سن مطالبات به تفکیک مشتری و بازهٔ سنی",
      "dimensions": [
        "customer",
        "aging_bucket"
      ],
      "measures": [
        "balance"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ccc",
      "description": "چرخهٔ تبدیل وجه نقد",
      "formula": "dio + dso - dpo",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات / فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "customer",
        "period"
      ]
    },
    {
      "metric": "dio",
      "description": "دورهٔ گردش موجودی",
      "formula": "موجودی / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dpo",
      "description": "دورهٔ پرداخت بستانکاران",
      "formula": "بستانکاران / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ccc"
    ],
    "period": [
      "prev_quarter",
      "curr_quarter"
    ],
    "comparison": "quarter_over_quarter"
  }
}

TOOL_OBSERVATION:
{
  "ccc_days": {
    "prev_quarter": 29,
    "curr_quarter": 52,
    "change": 23
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "working_capital_breakdown",
    "filters": {
      "period": [
        "prev_quarter",
        "curr_quarter"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
